.sc-tw *{
      box-sizing: border-box;
    }.sc-tw :root{
      color-scheme: dark;
    }.sc-tw html{
      scroll-behavior: smooth;
    }.sc-tw{
      margin: 0;
      overflow-x: hidden;
      background:
        radial-gradient(circle at top right, oklch(26% .08 250 / .25), transparent 24%),
        radial-gradient(circle at bottom left, oklch(28% .08 200 / .18), transparent 28%),
        oklch(9% .012 250);
      color: white;
      font-family: Inter, ui-sans-serif, system-ui;
    }.sc-tw body::before{
      content: "";
      position: fixed;
      inset: 0;
      background-image:
        linear-gradient(rgba(255,255,255,.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,.03) 1px, transparent 1px);
      background-size: 120px 120px;
      mask-image: radial-gradient(circle at center, black 20%, transparent 80%);
      pointer-events: none;
      opacity: .4;
    }.sc-tw .glass{
      position: relative;
      overflow: hidden;
      background:
        linear-gradient(180deg,
          rgba(255,255,255,.08),
          rgba(255,255,255,.02));
      border: 1px solid rgba(255,255,255,.08);
      backdrop-filter: blur(26px) saturate(180%);
      -webkit-backdrop-filter: blur(26px) saturate(180%);
      box-shadow:
        0 1px 0 rgba(255,255,255,.05) inset,
        0 -1px 0 rgba(255,255,255,.02) inset,
        0 30px 90px rgba(0,0,0,.45);
    }.sc-tw .glass::before{
      content: "";
      position: absolute;
      inset: 0;
      background:
        linear-gradient(
          130deg,
          transparent 20%,
          rgba(255,255,255,.14),
          transparent 80%
        );
      transform: translateX(-120%);
      animation: shine 10s linear infinite;
    }

    @keyframes shine {to{
        transform: translateX(120%);
      }
    }.sc-tw .noise::after{
      content: "";
      position: absolute;
      inset: 0;
      opacity: .05;
      background-image:
        radial-gradient(circle, white 1px, transparent 1px);
      background-size: 14px 14px;
      pointer-events: none;
    }.sc-tw .orb{
      position: absolute;
      border-radius: 999px;
      filter: blur(90px);
      pointer-events: none;
      mix-blend-mode: plus-lighter;
    }.sc-tw .portal{
      transform-style: preserve-3d;
      animation: portalFloat 12s ease-in-out infinite;
    }

    @keyframes portalFloat {0%,100%{
        transform: translateY(0px) rotate(-6deg);
      }50%{
        transform: translateY(-22px) rotate(-3deg);
      }
    }.sc-tw .kinetic{
      background:
        linear-gradient(
          90deg,
          rgba(255,255,255,.5),
          white,
          rgba(255,255,255,.5)
        );
      background-size: 200% auto;
      color: transparent;
      -webkit-background-clip: text;
      animation: shimmer 5s linear infinite;
    }

    @keyframes shimmer {to{
        background-position: 200% center;
      }
    }.sc-tw .liquid-btn{
      position: relative;
      overflow: hidden;
      isolation: isolate;
    }.sc-tw .liquid-btn::before{
      content: "";
      position: absolute;
      inset: 0;
      background:
        radial-gradient(circle at top left,
          rgba(255,255,255,.35),
          transparent 35%),
        linear-gradient(
          135deg,
          rgba(255,255,255,.18),
          rgba(255,255,255,.02)
        );
      mix-blend-mode: overlay;
    }.sc-tw .tilt{
      transition:
        transform .5s cubic-bezier(.16,1,.3,1),
        box-shadow .5s cubic-bezier(.16,1,.3,1);
    }.sc-tw .tilt:hover{
      transform:
        perspective(1200px)
        rotateX(5deg)
        rotateY(-5deg)
        translateY(-10px);
    }.sc-tw .reveal{
      opacity: 0;
      transform: translateY(50px) scale(.98);
      filter: blur(12px);
      transition:
        opacity 1s cubic-bezier(.16,1,.3,1),
        transform 1s cubic-bezier(.16,1,.3,1),
        filter 1s cubic-bezier(.16,1,.3,1);
      transition-timeline: view();
      transition-range: entry 10% cover 32%;
    }.sc-tw .reveal.active{
      opacity: 1;
      transform: translateY(0) scale(1);
      filter: blur(0);
    }.sc-tw .mask-video{
      mask-image:
        radial-gradient(circle at 70% 50%, black 40%, transparent 88%);
      -webkit-mask-image:
        radial-gradient(circle at 70% 50%, black 40%, transparent 88%);
    }.sc-tw .floating-card{
      animation: drift 8s ease-in-out infinite;
    }

